        data.musicAuthor = awemeInfoWithNetWork?.music?.author;
        data.musicDuration = awemeInfoWithNetWork?.music?.duration ?? 0;
        data.musicTitle = awemeInfoWithNetWork?.music?.title;
        data.collectCount = statistics?.collect_count ?? 0;
